class Solution {
public:
    vector<int> countPoints(vector<vector<int>>& points, vector<vector<int>>& queries) {
        vector<int> answer;
        answer.reserve(queries.size());
        for (const auto& q : queries) {
            int cx = q[0], cy = q[1], r = q[2];
            int r2 = r * r;
            int cnt = 0;
            for (const auto& p : points) {
                int dx = p[0] - cx;
                int dy = p[1] - cy;
                if (dx * dx + dy * dy <= r2) {
                    ++cnt;
                }
            }
            answer.push_back(cnt);
        }
        return answer;
    }
};
